ext('c10_eng_ch12',[
C("🏞️","मिथिला की धरती",["बिहार का सांस्कृतिक क्षेत्र","मधुबनी चित्रकला की जन्मभूमि","मैथिली भाषा और गीत","विद्यापति की कर्मभूमि"],"यह कविता हमारे अपने बिहार की माटी से जुड़ी है। मिथिला क्षेत्र अपनी कला, भाषा और परंपरा के लिए जाना जाता है। यहाँ की मधुबनी चित्रकला पूरी दुनिया में प्रसिद्ध है। यहाँ के शादी-ब्याह के गीत, सोहर और समदाउन मैथिली में गाए जाते हैं। और इसी धरती पर जन्मे महाकवि विद्यापति, जिनके पद आज भी हर घर में गूँजते हैं। जब हम अंग्रेज़ी की किताब में अपने ही बिहार के कवि को पढ़ते हैं, तो गर्व होना स्वाभाविक है। इसलिए इस पाठ को ख़ास ध्यान से पढ़िए।"),
C("✍️","विद्यापति का जीवन",["मिथिला के महाकवि","मैथिल कोकिल की उपाधि","राजा शिवसिंह के दरबारी","मैथिली, संस्कृत, अवहट्ट में रचना"],"विद्यापति चौदहवीं-पंद्रहवीं सदी के महाकवि थे। उन्हें मैथिल कोकिल यानी मिथिला की कोयल कहा जाता है, क्योंकि उनके गीत बहुत मधुर थे। वे राजा शिवसिंह के दरबार में रहे। उन्होंने मैथिली, संस्कृत और अवहट्ट भाषा में रचनाएँ कीं। उनकी पदावली में राधा और कृष्ण के प्रेम के पद हैं, और वे शिव भक्ति के गीत, यानी नचारी भी लिखते थे। कहा जाता है कि शिव स्वयं उगना नाम का सेवक बनकर उनके साथ रहे। परीक्षा में उनका परिचय पाँच-छह वाक्यों में लिखना आना चाहिए।"),
C("🌙","अर्धचंद्र की उपमा",["दूज का चाँद बहुत पतला","राधा उससे भी पतली","विरह में शरीर क्षीण","कल्पना और अतिशयोक्ति"],"कविता का शीर्षक है थिनर दैन अ क्रेसेंट, यानी अर्धचंद्र से भी पतली। दूज का चाँद आसमान में बहुत पतली रेखा जैसा दिखता है। कवि कहते हैं कि कृष्ण के वियोग में राधा इतनी दुबली हो गई हैं कि वह उस चाँद से भी पतली लगती हैं। यह कोई सच्चाई नहीं, कवि की कल्पना है, ताकि पाठक राधा की पीड़ा को गहराई से महसूस कर सके। जब प्रेम में बिछड़ना होता है, तो खाना-पीना और नींद भी छूट जाती है, और शरीर सचमुच कमज़ोर पड़ जाता है।"),
C("😢","आँसुओं का सरोवर",["राधा दिन-रात रोती हैं","आँसुओं से धरती पर गड्ढा","सखी का संदेश कृष्ण को","पीड़ा की चरम सीमा"],"कविता में दूसरी बड़ी कल्पना है आँसुओं की। राधा इतना रोती हैं कि उनके आँसुओं से धरती पर गड्ढा बन जाता है। यह भी अतिशयोक्ति है, पर इससे हमें राधा के दुख की गहराई समझ आती है। यहाँ राधा की सखी, कृष्ण को यह सब बता रही है। वह कह रही है कि अब तो आ जाओ, वरना राधा का हाल बहुत बुरा है। इस तरह सखी एक दूत की तरह काम करती है, जो प्रेमी तक प्रेमिका का संदेश पहुँचाती है। यह परंपरा भारतीय काव्य में बहुत पुरानी है।"),
C("📈","अतिशयोक्ति अलंकार",["बात को बढ़ा-चढ़ाकर कहना","अंग्रेज़ी में हाइपरबोली","भाव को गहरा बनाता है","चाँद से पतली, आँसुओं का सरोवर"],"इस कविता का मुख्य अलंकार अतिशयोक्ति है, जिसे अंग्रेज़ी में हाइपरबोली कहते हैं। इसमें किसी बात को इतना बढ़ा-चढ़ाकर कहा जाता है कि वह सच से परे लगे, पर भाव गहरा हो जाए। इस कविता में दो उदाहरण हैं। पहला, राधा अर्धचंद्र से भी पतली हैं। दूसरा, उनके आँसुओं से धरती पर गड्ढा बन गया। हमारी रोज़मर्रा की बातों में भी ऐसे प्रयोग होते हैं, जैसे मैं तो भूख से मरा जा रहा हूँ। परीक्षा में अलंकार का नाम, परिभाषा और दो उदाहरण, यह तीनों लिखना न भूलिए।"),
C("❤️","विरह शृंगार रस",["रस यानी कविता का आनंद","शृंगार रस प्रेम का रस","संयोग और वियोग दो रूप","यहाँ वियोग यानी विरह"],"संस्कृत काव्यशास्त्र में रस का मतलब है कविता पढ़ने से मिलने वाला भाव और आनंद। शृंगार रस प्रेम का रस है, और इसके दो रूप हैं। संयोग शृंगार में प्रेमी-प्रेमिका मिलते हैं और ख़ुश रहते हैं। वियोग या विरह शृंगार में वे बिछड़े हुए होते हैं और तड़पते हैं। इस कविता में कृष्ण दूर हैं और राधा तड़प रही हैं, इसलिए यहाँ विरह शृंगार रस है। विद्यापति इस रस के सबसे बड़े कवियों में गिने जाते हैं। परीक्षा में रस पूछा जाए तो विरह शृंगार लिखिए।"),
C("🔄","अनुवाद की चुनौती",["मैथिली से अंग्रेज़ी में","संगीत और लय अनुवाद में कम","फिर भी भाव सुरक्षित","मूल पद ज़रूर सुनिए"],"यह कविता मूल रूप से मैथिली में लिखी गई थी, जो बहुत मधुर और संगीत से भरी भाषा है। जब उसे अंग्रेज़ी में अनुवाद किया जाता है, तो शब्दों की मिठास और लय का कुछ हिस्सा खो जाता है। अनुवादक की यही सबसे बड़ी चुनौती होती है। फिर भी इस अनुवाद में राधा की पीड़ा का भाव सुरक्षित है। अगर आपके घर में कोई बुज़ुर्ग विद्यापति के पद गाते हों, तो उन्हें ज़रूर सुनिए। मूल पद सुनने का अनुभव अनुवाद से कहीं ज़्यादा सुंदर होता है।"),
C("📝","शब्दार्थ दोहराइए",["क्रेसेंट यानी अर्धचंद्र","थिन यानी पतला","टियर्स यानी आँसू","सेपरेशन और पेन"],"आइए शब्द दोहराते हैं। क्रेसेंट यानी अर्धचंद्र, थिन यानी पतला, टियर्स यानी आँसू, सेपरेशन यानी बिछड़ना, और पेन यानी पीड़ा। इनके साथ लव यानी प्रेम, फ्रेंड यानी सखी और मैसेज यानी संदेश भी याद रखिए। अब हर शब्द से एक वाक्य बनाइए। जैसे द मून इज़ थिन, यानी चाँद पतला है। और शी इज़ क्राइंग इन सेपरेशन, यानी वह बिछड़ने में रो रही है। अपने वाक्य कॉपी में लिखिए और बार-बार पढ़िए।"),
C("🧩","व्याकरण: कंपेरिज़न",["थिनर दैन यानी से ज़्यादा पतला","एज़ थिन एज़ यानी जितना पतला","सुपरलेटिव में द थिनेस्ट","तीन डिग्री याद रखिए"],"शीर्षक में ही तुलना का व्याकरण छिपा है। थिनर दैन का मतलब है से ज़्यादा पतला। अंग्रेज़ी में विशेषण की तीन डिग्री होती हैं। पहली, पॉज़िटिव, जैसे थिन। दूसरी, कंपेरेटिव, जैसे थिनर, जिसमें दो की तुलना होती है। तीसरी, सुपरलेटिव, जैसे थिनेस्ट, जिसमें कई में सबसे ऊपर बताया जाता है। थिन जैसे छोटे शब्द में आख़िरी अक्षर दोहराकर एर लगता है। एक और रूप है एज़ थिन एज़, यानी जितना पतला। इन तीनों रूपों से दो-दो वाक्य बनाकर अभ्यास कीजिए।"),
C("🎶","लोकगीतों में विद्यापति",["विवाह में गाए जाते पद","जगदंबा और शिव के गीत","भोज और उत्सवों में","पीढ़ी दर पीढ़ी जीवित परंपरा"],"विद्यापति के पद सिर्फ़ किताबों में नहीं, लोगों के कंठ में बसे हैं। मिथिला में शादी-ब्याह के अवसर पर उनके गीत गाए जाते हैं। शिव की नचारी, जैसे आजकल के भजन, बड़े भाव से गाई जाती हैं। नेपाल के कुछ हिस्सों तक में उनके पद गाए जाते हैं। छह सौ साल बाद भी उनकी रचनाएँ जीवित हैं, यह उनकी महानता का प्रमाण है। हमें भी चाहिए कि अपनी भाषा और संस्कृति का सम्मान करें और अपने बच्चों को इन गीतों से परिचित कराएँ।"),
C("🌸","प्रेम में संवेदना",["सच्चा प्रेम त्याग और समझ है","बिछड़ने की पीड़ा सबको होती है","दूसरों की भावनाओं को समझें","संवाद से दूरियाँ मिटती हैं"],"इस कविता से हम एक जीवन-मूल्य भी सीखते हैं। प्रेम केवल मिलने का नाम नहीं, बिछड़ने पर भी याद रखने का नाम है। राधा की पीड़ा हमें सिखाती है कि हर इंसान को अपनों के बिछड़ने का दुख होता है, चाहे वह माँ-बाप से दूर पढ़ने वाला विद्यार्थी हो या परदेस में काम करने वाला मज़दूर। हमें अपनों से संपर्क बनाए रखना चाहिए। एक फ़ोन कॉल या एक चिट्ठी किसी का मन हल्का कर सकती है। संवाद से दूरियाँ मिटती हैं और रिश्ते मज़बूत होते हैं।"),
C("📌","पूरी कविता का सार",["सखी का कृष्ण को संदेश","राधा विरह में बहुत दुबली","आँसुओं से धरती पर गड्ढा","अतिशयोक्ति और विरह शृंगार"],"आइए सार दोहरा लें। इस पद में राधा की सखी कृष्ण से कहती है कि राधा आपके बिना बहुत दुखी हैं। वे विरह में इतनी दुबली हो गई हैं कि दूज के चाँद से भी पतली लगती हैं। उनके आँसुओं से धरती पर गड्ढा बन गया है। कविता में अतिशयोक्ति अलंकार और विरह शृंगार रस है। यह विद्यापति की मैथिली रचना का अनुवाद है। इसी सार को अपने शब्दों में पाँच वाक्यों में लिखिए।"),
C("❓","संभावित परीक्षा प्रश्न",["कवि कौन हैं, परिचय दीजिए","राधा की हालत का वर्णन","कविता का अलंकार कौन सा है","सखी कृष्ण से क्या कहती है"],"अब परीक्षा के प्रश्न देखिए। पहला, कवि का परिचय दीजिए। उत्तर, विद्यापति, मिथिला के महाकवि, जिन्हें मैथिल कोकिल कहा जाता है। दूसरा, राधा की हालत का वर्णन कीजिए। उत्तर, वे विरह में चाँद से भी पतली हो गई हैं और रो-रोकर धरती पर गड्ढा बना चुकी हैं। तीसरा, अलंकार कौन सा है? उत्तर, अतिशयोक्ति। चौथा, सखी क्या कहती है? उत्तर, कि कृष्ण जल्दी आएँ और राधा की पीड़ा दूर करें। उत्तर पूरे वाक्य में लिखिए।"),
Q("आपके अनुसार कवि ने राधा की पीड़ा बताने के लिए बढ़ा-चढ़ाकर बातें क्यों कहीं?","ताकि पाठक राधा के दुख की गहराई को महसूस कर सके और भाव और गहरा हो जाए।","एक सोचने वाला प्रश्न। कवि ने राधा की पीड़ा बताने के लिए बढ़ा-चढ़ाकर बातें क्यों कहीं? सोचिए। ... इसलिए कि पाठक राधा के दुख की गहराई को सचमुच महसूस कर सके। जब बात बढ़ाकर कही जाती है, तो भाव और गहरा हो जाता है। यही अतिशयोक्ति का काम है।"),
],7)
